'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={back:'M19 12H5 M10 7l-5 5 5 5',home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',report:'M8 3h8l4 4v14H4V3z M8 11h8 M8 15h5',book:'M12 5c-3-2-7-2-10-1v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1z M12 5v15',check:'M9 12l2 2 4-5 M7 3H4v18h16V3h-3 M8 2h8v4H8z',tool:'M14 3a6 6 0 0 0-7 7L2 15a3 3 0 0 0 4 4l5-5a6 6 0 0 0 7-7l-4 4-3-3z',action:'M4 5h16 M4 12h10 M4 19h7 M16 16l2 2 4-5',learn:'M2 8l10-5 10 5-10 5z M6 10v7c4 3 8 3 12 0v-7 M22 8v9',bell:'M5 17h14l-2-3V8a5 5 0 0 0-10 0v6z M10 21h4',audit:'M3 4h18v16H3z M7 8h3 M7 12h3 M7 16h3 M14 9l2 2 3-4',group:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',plus:'M12 4v16 M4 12h16',close:'M6 6l12 12 M18 6L6 18',tick:'M5 12l4 4L19 6',temperature:'M9 14V5a3 3 0 0 1 6 0v9a5 5 0 1 1-6 0 M12 8v10',sun:'M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M9 22h6',menu:'M4 6h16 M4 12h16 M4 18h16',shield:'M12 2l8 3v7c0 5-8 10-8 10S4 17 4 12V5z M8 12l3 3 5-6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',clock:'M12 6v6l4 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',info:'M12 10v7 M12 6h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.info}"/></svg>`;
let state;try{state=JSON.parse(localStorage.getItem('pharmatap-demo-v1'));if(!state||state.schema!==1)state=seedState();}catch{state=seedState();}
let page=location.hash.slice(1)||'today',filter='',search='',askOpen=false,mobileOpen=false,reportDraft=null,reportStep=0;
const activeSites=()=>SITES.filter(s=>!s.pending),siteName=id=>SITES.find(s=>s.id===id)?.name||'Group',siteLabel=()=>state.site==='all'?'All pharmacies':siteName(state.site),scoped=arr=>arr.filter(r=>state.site==='all'||r.site===state.site),reviewer=()=>state.role!=='Staff',groupAdmin=()=>state.role==='Group admin';
const activeActions=()=>scoped(state.actions).filter(a=>a.status!=='Closed'),dueLabel=a=>a.due<DEMO_DATE?'Overdue':a.due===DEMO_DATE?'Due today':'Due '+formatDate(a.due);
// Keep the prior published sample visible while a revision is in draft.
function publishedSop(s){if(s.status!=='Draft')return s;const h=s.history.find(h=>!h.status||h.status==='Demo current');return h?{...s,...h,status:'Demo current',history:s.history.filter(x=>x.version!==h.version)}:null;}
function visibleSops(){return groupAdmin()?state.sops:state.sops.map(publishedSop).filter(Boolean);}
function knowledgeSop(id){return state.sops.map(publishedSop).filter(Boolean).find(s=>s.id===id);}
function formatDate(d){return new Date(d+'T12:00:00').toLocaleDateString('en-IE',{day:'numeric',month:'short'});}
function badge(label,tone=''){return `<span class="badge ${tone}">${esc(label)}</span>`;}
function btn(text,action,style='secondary',extra=''){return `<button class="button ${style}" data-action="${action}" ${extra}>${text}</button>`;}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function save(text,site=state.site){if(text)state.activity.unshift({text,time:new Date().toISOString(),site,role:state.role});try{localStorage.setItem('pharmatap-demo-v1',JSON.stringify(state));return true;}catch{toast('Browser storage is full. Changes are in memory only; export your demo data.');return false;}}
const pageHistory=[];
let navChoice='home';
function navigate(to){askOpen=false;navChoice=to==='today'?'home':'menu';if(to!==page)pageHistory.push({page,filter,search,scroll:window.scrollY});page=to;filter='';search='';mobileOpen=false;location.hash=to;render();window.scrollTo({top:0,behavior:'instant'});}
function goBack(){
 if(askOpen){askOpen=false;navChoice=page==='today'?'home':'menu';render();return;}
 navChoice='back';
 if(mobileOpen){mobileOpen=false;render();return;}
 const previous=pageHistory.pop();
 if(!previous){if(page!=='today')navigate('today');return;}
 page=previous.page;filter=previous.filter;search=previous.search;mobileOpen=false;location.hash=page;render();window.scrollTo({top:previous.scroll,behavior:'instant'});
}
function mobileNavigation(){const selected=askOpen?'ask':mobileOpen?'menu':navChoice,index=['back','home','menu','ask'].indexOf(selected);return `<nav class="mobile-navigation" aria-label="Quick navigation"><span class="nav-highlight" aria-hidden="true" style="transform:translateX(${index*100}%)"></span><button data-action="back" aria-label="Back" ${selected==='back'?'class="selected"':''} ${page==='today'&&!pageHistory.length&&!mobileOpen&&!askOpen?'disabled':''}>${icon('back')}<span>Back</span></button><button data-nav="today" aria-label="Home" ${selected==='home'?'class="selected"':''}>${icon('home')}<span>Home</span></button><button data-action="menu" aria-label="Menu" ${selected==='menu'?'class="selected"':''} aria-expanded="${mobileOpen}" aria-controls="navigation-drawer">${icon(mobileOpen?'close':'menu')}<span>Menu</span></button><button data-action="ask" aria-label="Ask PharmaTap" ${selected==='ask'?'class="selected"':''} aria-expanded="${askOpen}" aria-controls="ask-root">${icon('spark')}<span>Ask</span></button></nav>`;}
const NAV=[['today','home','Today'],['reports','report','Reports'],['sops','book','SOP Library'],['checks','check','Checks'],['maintenance','tool','Maintenance'],['actions','action','Actions'],['learning','learn','Learning'],['recalls','bell','Recalls'],['inspections','audit','Inspections']];
function render(){
 const oldHighlight=$('.nav-highlight'),previousTransform=oldHighlight?getComputedStyle(oldHighlight).transform:null;
 if(!NAV.some(n=>n[0]===page)&&!['group','blueprint','activity'].includes(page))page='today';
 if(!groupAdmin()&&page==='group')page='today';
 if(!groupAdmin()&&state.site==='all')state.site='skerries';
 $('#app').innerHTML=`<div class="mobile-shade ${mobileOpen?'open':''}" data-action="menu"></div><div class="app-shell"><aside id="navigation-drawer" class="sidebar ${mobileOpen?'open':''}"><div class="brand"><img src="assets/mark.svg" alt="">PharmaTap</div><div class="client"><img src="assets/stacks-logo.png" alt="Stacks Pharmacy"><span>Stacks Pharmacy<br><small class="muted">Quality & operations</small></span></div><nav aria-label="Main navigation"><div class="nav-group">Your pharmacy</div>${NAV.map(([id,ic,title])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}${title}</button>`).join('')}${groupAdmin()?`<div class="nav-group">Your group</div><button data-nav="group" class="${page==='group'?'active':''}">${icon('group')}Group Overview</button>`:''}</nav><div class="nav-footer"><button data-nav="blueprint">${icon('info')} Product blueprint</button><button data-nav="activity">${icon('clock')} Demo activity</button><small class="muted">PharmaTap · v1.0</small></div></aside><header class="topbar"><div class="context"><button class="menu-toggle" data-action="menu" aria-label="Open navigation">${icon('menu')}</button>${icon('group')}<select id="site-select" aria-label="Pharmacy">${groupAdmin()?'<option value="all">All pharmacies</option>':''}${activeSites().map(s=>`<option value="${s.id}" ${s.id===state.site?'selected':''}>${s.name}</option>`).join('')}</select></div><div class="context"><span class="demo-pill">Demo</span><select id="role-select" aria-label="Demo role">${['Staff','Pharmacist','Group admin'].map(r=>`<option ${r===state.role?'selected':''}>${r}</option>`).join('')}</select><span class="avatar" title="Demo colleague">SP</span></div></header><main class="main" id="main" tabindex="-1">${renderPage()}<p class="footer-note">Demo · 5 October 2026 · Fictional information only.<br>Changes stay in this browser. Role switching is for demonstration; there is no secure sign-in.</p></main>${mobileNavigation()}${!askOpen?`<button class="ask-fab" data-action="ask" aria-label="Ask PharmaTap" title="Ask PharmaTap">${icon('spark')}</button>`:''}</div><div id="ask-root"></div>`;
 if(state.site==='all')$('#site-select').value='all';
 if(askOpen)renderAsk();
 const highlight=$('.nav-highlight');if(previousTransform&&highlight&&!matchMedia('(prefers-reduced-motion: reduce)').matches)highlight.animate([{transform:previousTransform},{transform:highlight.style.transform}],{duration:320,easing:'cubic-bezier(.22,1,.36,1)'});
}
function heading(title,subtitle,button=''){return `<div class="page-heading"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${button}</div>`;}
function metric(number,label,caption){return `<div class="card metric"><div class="label">${label}</div><div class="number">${number}</div><div class="caption">${caption}</div></div>`;}
function searchbar(placeholder,options=''){return `<div class="toolbar"><div class="search">${icon('search')}<input id="search" type="search" placeholder="${placeholder}" value="${esc(search)}" aria-label="${placeholder}"></div>${options}</div>`;}
const row=(title,sub,ic,action,right='')=>`<button class="row row-button" data-action="${action}"><span class="check-circle">${icon(ic)}</span><span class="row-content"><h3>${title}</h3><p>${sub}</p></span>${right||`<span class="chevron">${icon('chevron')}</span>`}</button>`;
function checkRows(){return CHECK_TEMPLATES.map(t=>{const completed=state.checks.find(c=>c.site===state.site&&c.template===t.id&&c.date===DEMO_DATE);return `<button class="row row-button" data-action="check:${t.id}"><span class="check-circle ${completed?'done':''}">${icon(completed?'tick':t.icon)}</span><span class="row-content"><h3>${t.title}</h3><p>${completed?esc(completed.result):t.subtitle+' · '+t.time}</p></span>${completed?badge('Recorded',completed.result==='Needs review'?'amber':''):icon('chevron')}</button>`;}).join('');}
function today(){
 const tasks=[
  ['report','Report an issue','Near miss, error or concern','data-action="new-report"'],
  ['book','Find a procedure','Search your SOPs','data-nav="sops"'],
  ['check','Complete a check','Daily pharmacy checks','data-nav="checks"'],
  ['tool','Report a fault','Equipment or premises','data-action="new-maintenance"'],
  ['action','View my actions','See what needs attention','data-nav="actions"'],
  ['learn','Complete learning','Training and updated SOPs','data-nav="learning"']
 ];
 const recallNeedsResponse=state.site==='all'
  ? activeSites().some(s=>!state.recall.responses.some(r=>r.site===s.id&&r.status==='Confirmed'))
  : !state.recall.responses.some(r=>r.site===state.site&&r.status==='Confirmed');
 return heading('Today',`${siteLabel()} · Monday, 5 October`)+`<section class="home-tasks" aria-label="Pharmacy tasks">${tasks.map(([ic,title,sub,target])=>`<button class="card home-task clickable" ${target}><span class="icon-box">${icon(ic)}</span><span class="task-title">${title}</span><span class="task-description">${sub}</span></button>`).join('')}</section>${recallNeedsResponse?`<div class="home-recall notice"><span>${icon('bell')} Sample recall needs a response</span>${btn('View recall','nav:recalls','secondary sm')}</div>`:''}`;
}
function reportsPage(){const list=scoped(state.reports).filter(r=>(!filter||r.type===filter)&&(r.title+' '+r.id+' '+r.category+' '+siteName(r.site)).toLowerCase().includes(search.toLowerCase()));return heading('Reports','',btn(`${icon('plus')} New report`,'new-report',''))+searchbar('Search reports',`<select id="filter" aria-label="Report type"><option value="">All reports</option>${['Near miss','Medication error','Complaint','Safety concern'].map(t=>`<option ${filter===t?'selected':''}>${t}</option>`).join('')}</select>`)+`<div class="table-wrap"><table><thead><tr><th>Report</th><th>Pharmacy</th><th>Type</th><th>Status</th></tr></thead><tbody>${list.map(r=>`<tr data-id="report:${r.id}" tabindex="0" role="button" aria-label="Open ${esc(r.id)}"><td>${esc(r.title)}<span class="small">${r.id} · ${formatDate(r.date)}</span></td><td>${siteName(r.site)}</td><td>${badge(r.type,r.type==='Medication error'?'red':'gray')}</td><td>${badge(r.status,r.status==='Closed'?'':'amber')}</td></tr>`).join('')}</tbody></table>${!list.length?'<p class="empty">No reports match your search.</p>':''}</div><div class="notice green section">More near-miss reports may reflect better reporting, not poorer safety.</div>`;}
function sopPage(){const categories=[...new Set(visibleSops().map(s=>s.category))],list=visibleSops().filter(s=>(!filter||s.category===filter)&&(s.title+' '+s.id+' '+s.objective).toLowerCase().includes(search.toLowerCase()));return heading('SOP Library','',groupAdmin()?btn(`${icon('plus')} Add sample SOP`,'new-sop',''):'')+searchbar('Search procedures',`<select id="filter" aria-label="Procedure category"><option value="">All categories</option>${categories.map(c=>`<option ${filter===c?'selected':''}>${c}</option>`).join('')}</select>`)+`<div class="grid three">${list.map(s=>`<button class="card sop-card clickable" data-action="sop:${s.id}" style="text-align:left;color:inherit"><div class="buttons">${icon('book')}<small class="muted">${esc(s.category)}</small></div><h3>${esc(s.title)}</h3><p class="small muted">${esc(s.objective)}</p><div class="bottom"><small class="muted">${s.id} · v${esc(s.version)}</small>${badge(state.acknowledgements.some(a=>a.sop===s.id&&a.version===s.version&&a.site===state.site&&a.role===state.role)?'Acknowledged':s.status,s.status==='Draft'?'amber':'gray')}</div></button>`).join('')}</div>${!list.length?'<p class="empty">No procedures match. Try a different search.</p>':''}<p class="footer-note">${state.sops.length} sample SOPs. These are illustrative workflows, not approved Stacks procedures. The production library can hold hundreds of client-approved documents.</p>`;}
function checksPage(){const records=scoped(state.checks).filter(c=>c.date===DEMO_DATE);return heading('Checks','Monday, 5 October · sample schedule')+`<div class="grid two"><div class="card"><div class="card-header"><h2>Today’s checks</h2>${badge(records.length+' recorded')}</div>${state.site==='all'?'<p class="muted">Choose a pharmacy above to record its checks.</p>':checkRows()}</div><div class="card"><h2>Recorded today</h2><div style="margin-top:22px">${records.slice().reverse().map(c=>`<button class="row row-button" data-action="check-record:${c.id}"><span class="check-circle done">${icon('tick')}</span><span class="row-content"><h3>${CHECK_TEMPLATES.find(t=>t.id===c.template)?.title||c.template}</h3><p>${siteName(c.site)} · ${esc(c.result)}</p></span>${badge(c.current!==undefined?c.current+'°C':'View',c.result==='Needs review'?'amber':'')}</button>`).join('')||'<p class="empty">No checks recorded yet.</p>'}</div></div></div><div class="notice section">The demo checks fridge readings against 2–8°C and room readings against 25°C. Production limits, timings and escalation rules must be approved for each site and stock type. Any exception creates a review action; it does not decide whether medicines are suitable for use.</div>`;}
function maintenancePage(){const list=scoped(state.maintenance).filter(m=>(m.title+' '+m.asset+' '+siteName(m.site)).toLowerCase().includes(search.toLowerCase()));return heading('Maintenance','',btn(`${icon('plus')} Report a fault`,'new-maintenance',''))+searchbar('Search maintenance')+`<div class="grid three">${list.map(m=>`<button class="card clickable" data-action="maintenance:${m.id}" style="text-align:left;color:inherit"><div class="card-header">${icon('tool')}${badge(m.status,m.status==='Completed'?'':m.priority==='Urgent'?'red':'amber')}</div><h3>${esc(m.title)}</h3><p class="small muted" style="margin:10px 0">${esc(m.asset)}</p><p class="small muted">${siteName(m.site)} · ${esc(m.owner)}</p></button>`).join('')}</div>${!list.length?'<p class="empty">No maintenance items match.</p>':''}<section class="section"><div class="card"><h2>Asset register · sample</h2><div class="row"><div class="row-content"><h3>Pharmaceutical fridge · FR-01</h3><p>Servicing, validation, fault history and evidence</p></div>${btn('View maintenance SOP','sop:SOP-009','ghost')}</div><div class="row"><div class="row-content"><h3>Room thermometer · TM-02</h3><p>Calibration schedule and certificate history</p></div>${btn('View calibration SOP','sop:SOP-010','ghost')}</div></div></section>`;}
function actionsPage(){const list=scoped(state.actions).filter(a=>(!filter||a.status===filter)&&(a.title+' '+a.owner+' '+a.source).toLowerCase().includes(search.toLowerCase()));return heading('Actions','',reviewer()?btn(`${icon('plus')} Add an action`,'new-action',''):'')+searchbar('Search actions',`<select id="filter" aria-label="Action status"><option value="">All statuses</option>${['Open','Awaiting review','Closed'].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select>`)+`<div class="table-wrap"><table><thead><tr><th>Action</th><th>Owner</th><th>Due</th><th>Status</th></tr></thead><tbody>${list.map(a=>`<tr data-id="action:${a.id}" tabindex="0" role="button" aria-label="Open action ${a.id}"><td>${esc(a.title)}<span class="small">${siteName(a.site)} · ${esc(a.source)}</span></td><td>${esc(a.owner)}</td><td>${badge(a.status==='Closed'?formatDate(a.due):dueLabel(a),a.status==='Closed'?'gray':a.due<DEMO_DATE?'red':'gray')}</td><td>${badge(a.status,a.status==='Closed'?'':'amber')}</td></tr>`).join('')}</tbody></table>${!list.length?'<p class="empty">No actions match your search.</p>':''}</div>`;}
const LESSONS=[{id:'near-miss',title:'Spot it. Report it. Learn from it.',sop:'SOP-002',ic:'shield',minutes:3,description:'A quick refresher on near-miss reporting.',question:'When should a near miss be recorded?',answers:['Only if a patient complains','When an error is intercepted before it reaches the patient','Only after the same error happens twice'],correct:1},{id:'cold-chain',title:'A confident cold chain.',sop:'SOP-003',ic:'temperature',minutes:4,description:'Readings, exceptions and pharmacist review.',question:'What should you do when a recorded temperature is outside the approved limits?',answers:['Discard the reading and try again later','Decide independently whether the stock can be used','Escalate to the pharmacist and follow the approved procedure'],correct:2},{id:'sop-change',title:'A procedure has changed.',sop:'SOP-015',ic:'book',minutes:2,description:'Know which version applies to your work.',question:'Which SOP version should staff use?',answers:['The current approved version applicable to their role and site','Any version they have previously printed','The shortest available version'],correct:0}];
function learningPage(){return heading('Learning','Refreshers and SOP acknowledgements')+`<div class="grid three">${LESSONS.map(l=>`<div class="card learning-card"><div class="learning-art">${icon(l.ic)}</div><small class="eyebrow muted">${l.minutes} minute refresher</small><h3 style="margin-top:12px">${l.title}</h3><p>${l.description}</p>${state.learning.some(x=>x.id===l.id&&x.site===state.site&&x.role===state.role)?badge('Completed'):btn('Start refresher '+icon('arrow'),'lesson:'+l.id,'')}</div>`).join('')}</div><section class="section card"><div class="card-header"><h2>Your acknowledgements</h2>${btn('Browse SOPs','nav:sops','ghost')}</div>${state.acknowledgements.filter(a=>a.site===state.site&&a.role===state.role).map(a=>`<div class="row"><span class="check-circle done">${icon('tick')}</span><div class="row-content"><h3>${esc(state.sops.find(s=>s.id===a.sop)?.title||a.sop)}</h3><p>${a.sop} · version ${esc(a.version)} · ${new Date(a.time).toLocaleDateString('en-IE')}</p></div>${badge(knowledgeSop(a.sop)?.version===a.version?'Current':'New version available',knowledgeSop(a.sop)?.version===a.version?'':'amber')}</div>`).join('')||'<p class="muted small">Read and acknowledge a SOP to see it here.</p>'}</section><p class="footer-note">Demo refreshers illustrate a workflow; they do not certify clinical competence.</p>`;}
function recallsPage(){const r=state.recall,responses=state.site==='all'?r.responses:r.responses.filter(x=>x.site===state.site),done=r.responses.filter(x=>x.status==='Confirmed').length;return heading('Recalls','' )+`<div class="notice section" style="margin-bottom:22px">Recall exercise only. This is a fictional product and batch, not a current HPRA notice.</div><div class="card"><div class="card-header">${badge('Sample recall','amber')}<small class="muted">${r.id}</small></div><h2>${r.title}</h2><dl class="detail-grid"><div><dt>Product</dt><dd>${r.product}</dd></div><div><dt>Batch</dt><dd>${r.batch}</dd></div></dl><p class="small muted">${r.instructions}</p><div class="section"><div class="split-label"><small class="muted">Confirmed responses</small><small>${done} / ${activeSites().length}</small></div><div class="progress" style="margin-top:10px"><span style="width:${done/activeSites().length*100}%"></span></div></div><div class="buttons section">${state.site!=='all'&&!responses.length?btn('Record site response','recall-response',''):state.site!=='all'?badge(responses[0].status==='Confirmed'?'Site response confirmed':'Awaiting pharmacist review',responses[0].status==='Confirmed'?'':'amber'):''}${btn('Read recall procedure','sop:SOP-006','secondary')}<a class="button ghost" href="${SOURCES.recalls}" target="_blank" rel="noopener">HPRA recall guidance ${icon('arrow')}</a></div></div><section class="section card"><h2>Site responses</h2><div style="margin-top:18px">${responses.map(x=>`<div class="row"><div class="row-content"><h3>${siteName(x.site)}</h3><p>${x.quantity} packs found · ${esc(x.by)}</p></div>${badge(x.status,x.status==='Confirmed'?'':'amber')}${x.status!=='Confirmed'&&reviewer()?btn('Confirm','recall-confirm:'+x.site,'secondary sm'):''}</div>`).join('')||'<p class="muted small">No response recorded yet.</p>'}</div></section>`;}
function inspectionsPage(){return heading('Inspections','',btn(`${icon('download')} Print evidence pack`,'print-pack',''))+`<div class="grid three">${metric(scoped(state.checks).length,'Check records','Available in this demo')}${metric(scoped(state.reports).length,'Incident records','Summary without patient identifiers')}${metric(scoped(state.audits).length,'Internal reviews','Findings and follow-up actions')}</div><section class="section grid two"><div class="card"><h2>Internal review</h2><p class="muted small" style="margin:12px 0 22px">Record findings and assign actions.</p>${btn('Start review','new-audit','')}</div><div class="card"><h2>Evidence, in one place</h2><p class="muted small" style="margin-top:12px">Includes SOPs, checks, incident summaries, maintenance and actions for the selected pharmacies.</p><p class="muted small" style="margin-top:12px">Records support inspection review; they do not certify compliance.</p></div></section><section class="section card"><h2>Completed internal reviews</h2><div style="margin-top:18px">${scoped(state.audits).map(a=>`<button class="row row-button" data-action="audit:${a.id}"><div class="row-content"><h3>${esc(a.title)}</h3><p>${siteName(a.site)} · ${formatDate(a.date)} · ${a.findings.length} findings</p></div>${icon('chevron')}</button>`).join('')||'<p class="muted small">No internal reviews yet.</p>'}</div></section>`;}
function groupPage(){const allActions=state.actions.filter(a=>a.status!=='Closed'),openReports=state.reports.filter(r=>r.status!=='Closed'),confirmed=activeSites();return heading('Group Overview','16 named pharmacies · 4 awaiting confirmation',btn('Export demo data','export','secondary'))+`<div class="grid four">${metric(confirmed.length,'Named pharmacies','From Stacks’ public branch locator')}${metric(allActions.length,'Open actions',allActions.filter(a=>a.due<DEMO_DATE).length+' overdue')}${metric(openReports.length,'Reports in review','Pharmacist-led follow-up')}${metric(state.recall.responses.filter(x=>x.status==='Confirmed').length+'/'+confirmed.length,'Recall responses','Fictional recall exercise')}</div><section class="section"><div class="section-title"><h2>Your pharmacies</h2><small class="muted">Sample operational data</small></div><div class="grid three">${SITES.map(s=>{if(s.pending)return `<div class="card site-tile pending"><div class="top">${icon('group')}${badge('Unconfirmed','gray')}</div><h3>${s.name}</h3><p class="muted small">Name and setup awaiting confirmation</p><p class="footer-note">Excluded from operational totals.</p></div>`;const a=state.actions.filter(x=>x.site===s.id&&x.status!=='Closed'),c=state.checks.filter(x=>x.site===s.id&&x.date===DEMO_DATE);return `<button class="card site-tile clickable" data-action="site:${s.id}" style="text-align:left;color:inherit"><div class="top">${icon('group')}${badge(a.length?'Needs attention':'No open actions',a.length?'amber':'')}</div><h3>${s.name}</h3><p class="muted small">${s.county}</p><div class="site-stats"><div><strong>${c.length}/5</strong><span>Checks today</span></div><div><strong>${a.length}</strong><span>Open actions</span></div></div><div class="progress"><span style="width:${c.length/5*100}%"></span></div></button>`;}).join('')}</div></section><section class="section grid two"><div class="card"><h2>Learning from reports</h2><p class="small muted" style="margin-top:10px">Current sample records by pharmacy. Counts show reporting activity, not a safety ranking.</p><div class="bar-chart">${['skerries','marley','gorey'].map(id=>`<div class="bar-group"><div class="bar" style="height:${state.reports.filter(r=>r.site===id&&r.type==='Near miss').length*60}px" title="${siteName(id)} near misses"></div><div class="bar alt" style="height:${state.reports.filter(r=>r.site===id&&r.type==='Medication error').length*60}px" title="${siteName(id)} medication errors"></div><label>${siteName(id)}</label></div>`).join('')}</div><div class="legend"><span>● Near misses</span><span style="color:#b98e73">● Medication errors</span></div><p class="small muted">Production reporting should include activity denominators, severity and action effectiveness before comparing sites.</p></div><div class="card"><h2>What deserves attention?</h2><div style="margin-top:20px">${allActions.slice(0,4).map(a=>row(esc(a.title),siteName(a.site)+' · '+dueLabel(a),'action','action:'+a.id)).join('')}</div></div></section>`;}
function blueprintPage(){return heading('Product blueprint','PharmaTap for Stacks Pharmacy')+`<section class="hero"><div><span class="eyebrow">The idea</span><h2>Pharmacy quality and operations</h2><p>Procedures, checks, reports, actions and learning in one place.</p></div><div class="hero-art"><img src="assets/mark.svg" alt=""></div></section><div class="grid two"><div class="card"><h2>For the colleague</h2><div class="blueprint-item"><h3>One clear next step</h3><p>Find a procedure, record a check, report a concern or complete a short refresher.</p></div><div class="blueprint-item"><h3>Ask in everyday language</h3><p>Search approved SOPs with source references, or turn a typed/spoken account into a draft report for confirmation.</p></div><div class="blueprint-item"><h3>Safe handover</h3><p>Patient care takes priority. Medication incidents go to the appropriate pharmacist for assessment and follow-up.</p></div></div><div class="card"><h2>For the group</h2><div class="blueprint-item"><h3>Group and local SOPs</h3><p>Group SOPs, controlled local variations, site assignments and individual staff acknowledgements.</p></div><div class="blueprint-item"><h3>Actions and evidence</h3><p>Assigned owners, deadlines, completion evidence, pharmacist review and an effectiveness check.</p></div><div class="blueprint-item"><h3>Shared learning</h3><p>Share anonymised incident learning and track the resulting procedure changes and training.</p></div></div></div><section class="section card"><h2>The connected workflow</h2><div class="grid three section">${[['1','Capture','A colleague reports a near miss.'],['2','Review','The pharmacist checks the facts and contributing factors.'],['3','Act','An owner completes the preventive action.'],['4','Update','A controlled SOP revision is reviewed and published.'],['5','Learn','Affected colleagues acknowledge the change and complete training.'],['6','Verify','The reviewer checks whether the improvement worked.']].map(([n,t,d])=>`<div><span class="intro-num">${n}</span><h3 style="margin:12px 0 5px">${t}</h3><p class="muted small">${d}</p></div>`).join('')}</div></section><section class="section"><h2 style="margin-bottom:18px">Build stages</h2><div class="grid three"><div class="card"><span class="build-stage">01 · First release</span><h3>Knowledge + reporting</h3><p class="muted small section">Approved SOP library and cited search. Errors, near misses, maintenance, shared actions. Role-based access and audit history.</p></div><div class="card"><span class="build-stage">02 · Daily operations</span><h3>Checks + learning</h3><p class="muted small section">Schedules, exception workflows, assets, calibration, acknowledgements, induction and short refreshers.</p></div><div class="card"><span class="build-stage">03 · Group assurance</span><h3>Oversight + evidence</h3><p class="muted small section">Recalls, internal audits, inspection packs, cross-site learning and agreed integrations.</p></div></div></section><section class="section card"><h2>Roles and responsibilities</h2><div class="table-wrap section"><table><thead><tr><th>Role</th><th>Proposed access</th></tr></thead><tbody><tr><td>Staff / technician</td><td>Assigned-site checks, reporting, SOPs and learning; no clinical incident sign-off.</td></tr><tr><td>Pharmacy manager</td><td>Operational assignments and maintenance; clinical permissions only if separately authorised.</td></tr><tr><td>Supervising pharmacist</td><td>Site incident review, SOP implementation, corrective actions and clinical sign-off.</td></tr><tr><td>Superintendent / group governance</td><td>Group scope, SOP approval, controlled local variations and governance reporting.</td></tr><tr><td>Contractor</td><td>Only assigned maintenance work and evidence; no patient safety records.</td></tr></tbody></table></div><p class="small muted section">The demo simplifies these into Staff, Pharmacist and Group admin views. Production roles must be configured and enforced on the server.</p></section><section class="section card"><h2>From demo to a live service</h2><div class="blueprint-item"><h3>Shared, secure records</h3><p>Authenticated named users, organisation/site scope, controlled patient information, protected attachments, retention rules, append-only audit history and tested backups.</p></div><div class="blueprint-item"><h3>Controlled knowledge</h3><p>Import the client’s SOPs, confirm ownership and approval, extract searchable text, index only the current applicable versions, and show exact source passages. AI proposes; authorised people approve.</p></div><div class="blueprint-item"><h3>Dependable operations</h3><p>Scheduled jobs, escalation notifications, retries, monitoring, accessible mobile flows, duplicate protection and server-calculated reporting definitions.</p></div><div class="blueprint-item"><h3>Existing clinical systems</h3><p>Keep dispensing and clinical records in their designated systems. Integrations and any statutory registers are separate scoped work; this demo does not replace them.</p></div></section><section class="section card"><h2>Evidence and assumptions</h2><p class="small muted section">Branch names come from the public locator checked on 4 October 2026. It lists 16 names; the homepage states 18 branches, while the proposed project is for 20. Four unconfirmed slots are visible and excluded from operating totals. All reports, checks, faults, staff and recalls are fictional. The 24 sample SOPs are design illustrations requiring client pharmacist review.</p><div class="buttons section"><a href="${SOURCES.locations}" target="_blank" rel="noopener" class="button secondary">Stacks branch locator</a><a href="${SOURCES.errors}" target="_blank" rel="noopener" class="button secondary">PSI error management</a><a href="${SOURCES.sops}" target="_blank" rel="noopener" class="button secondary">PSI SOP guidance</a><a href="${SOURCES.storage}" target="_blank" rel="noopener" class="button secondary">PSI storage guidance</a><a href="${SOURCES.recalls}" target="_blank" rel="noopener" class="button secondary">HPRA recall guidance</a></div></section><section class="section card"><h2>Try the workflow</h2><ol class="small muted" style="line-height:2"><li>At Skerries, report a near miss and review the saved record.</li><li>As Pharmacist, add a preventive action; submit evidence and review its effectiveness.</li><li>As Group admin, revise a sample SOP and publish the demo version.</li><li>As Staff, acknowledge the revised SOP and complete a refresher.</li><li>Record a fridge check, report a fault and respond to the recall exercise.</li><li>Open Group Overview and print an evidence pack.</li></ol></section>`;}
function activityPage(){const list=scoped(state.activity).concat(state.activity.filter(a=>a.site==='group'&&state.site!=='all'));return heading('Demo activity','Newest first',`<div class="buttons">${btn('Export demo data','export','secondary')}${btn('Reset demo','reset','secondary')}</div>`)+`<div class="card">${list.map(a=>`<div class="audit-row">${esc(a.text)}<p>${esc(a.role)} · ${siteName(a.site)} · ${new Date(a.time).toLocaleString('en-IE')}</p></div>`).join('')}</div><p class="footer-note">This is a local demonstration log. Production audit records require server-enforced integrity, identity and retention.</p>`;}
function renderPage(){return ({today,reports:reportsPage,sops:sopPage,checks:checksPage,maintenance:maintenancePage,actions:actionsPage,learning:learningPage,recalls:recallsPage,inspections:inspectionsPage,group:groupPage,blueprint:blueprintPage,activity:activityPage}[page]||today)();}
function modal(title,body,eyebrow='PharmaTap'){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><div><span class="eyebrow muted">${eyebrow}</span><h2>${title}</h2></div><button class="close" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();d.scrollTop=0;}
function closeModal(){$('#dialog').close();reportDraft=null;}
const siteField=()=>`<label for="form-site">Pharmacy</label><select id="form-site" name="site" required>${activeSites().map(s=>`<option value="${s.id}" ${s.id===state.site?'selected':''}>${s.name}</option>`).join('')}</select>`;
function formFooter(text='Save',action=''){return `<div class="dialog-actions">${btn('Cancel','close','ghost')}<button type="submit" class="button" ${action?`data-action="${action}"`:''}>${text} ${icon('arrow')}</button></div>`;}
function newReport(type='',description=''){reportDraft={type,site:state.site==='all'?'skerries':state.site,description,category:'Selection',stage:'Final check',patient:type==='Near miss'?'No':'Yes',title:'',identified:'2026-10-05T09:30',medicineIntended:'',medicineObserved:'',factor:'Not yet established',immediate:'',severity:'Requires pharmacist assessment',photo:''};reportStep=type?1:0;reportWizard();}
function reportWizard(){const d=reportDraft;if(!d)return;const track=`<div class="step-track">${[0,1,2,3].map(n=>`<span class="${n<=reportStep?'active':''}"></span>`).join('')}</div><small class="muted">Step ${reportStep+1} of 4</small>`;let body;
 if(reportStep===0){body=track+`<p class="muted small" style="margin-top:12px">Choose a report type.</p><div class="option-grid">${[['Near miss','Caught before it reached the patient.','shield'],['Medication error','An error that needs pharmacist review.','report'],['Complaint','A concern about the service.','bell'],['Safety concern','A premises, staff or security concern.','tool']].map(([t,sub,i])=>`<button class="option" data-action="report-type:${t}">${icon(i)}<strong>${t}</strong><small>${sub}</small></button>`).join('')}</div>`;modal('What are you reporting?',body,'New report');return;}
 if(reportStep===1){body=track+`<form id="report-facts">${siteField()}<label for="report-title">Title</label><input id="report-title" name="title" value="${esc(d.title)}" placeholder="e.g. Different strength caught at final check" maxlength="120" required><label for="identified">When was it identified? · demo time</label><input type="datetime-local" id="identified" name="identified" value="${esc(d.identified)}" required><div class="split-label"><label for="description">What happened?</label>${btn(icon('mic')+' Dictate','dictate:description','ghost')}</div><textarea id="description" name="description" required placeholder="Use fictional details for this demo." maxlength="2500">${esc(d.description)}</textarea><p class="field-note">No patient names, dates of birth or prescription photos.</p><div class="grid two"><div><label for="category">Category</label><select id="category" name="category">${['Selection','Wrong medicine','Wrong strength','Labelling','Directions','Quantity','Handover','Service','Equipment','Other'].map(x=>`<option ${x===d.category?'selected':''}>${x}</option>`).join('')}</select></div><div><label for="stage">Stage identified</label><select id="stage" name="stage">${['Receipt','Assessment','Picking','Preparation','Final check','Supply','After supply','Other'].map(x=>`<option ${x===d.stage?'selected':''}>${x}</option>`).join('')}</select></div></div>${['Near miss','Medication error'].includes(d.type)?`<details style="margin-top:20px"><summary class="small muted" style="cursor:pointer">Medicine and contributing factors · optional</summary><label for="medicine-intended">Intended medicine / strength · fictional</label><input id="medicine-intended" name="medicineIntended" value="${esc(d.medicineIntended)}" maxlength="160"><label for="medicine-observed">Selected or supplied medicine / strength · fictional</label><input id="medicine-observed" name="medicineObserved" value="${esc(d.medicineObserved)}" maxlength="160"><label for="factor">Possible contributing factor</label><select id="factor" name="factor">${['Not yet established','Similar packaging','Shelf layout','Interruption','Workload','Communication','Process / handover','Other'].map(x=>`<option ${x===d.factor?'selected':''}>${x}</option>`).join('')}</select><p class="field-note">A pharmacist validates contributing factors during review.</p></details>`:''}<label for="photo">Optional evidence image</label><input type="file" id="photo" accept="image/*" capture="environment"><p class="field-note">Fictional or non-patient evidence only · maximum 500 KB · local demo storage.</p>${d.photo?'<small class="muted">Image attached.</small>':''}<div class="dialog-actions">${btn('Back','report-back','ghost')}<button class="button" type="submit">Continue ${icon('arrow')}</button></div></form>`;}
 if(reportStep===2){body=track+`<form id="report-response"><div class="notice ${d.type==='Medication error'?'red':'green'} section">${d.type==='Medication error'?'Patient care takes priority. Notify the pharmacist on duty promptly; recording an incident does not replace the clinical response.':'Notify the responsible colleague and record the immediate steps taken.'}</div>${['Near miss','Medication error'].includes(d.type)?`<label for="patient">Did the error reach the patient?</label><select name="patient" id="patient" ${d.type==='Near miss'?'disabled':''}><option ${d.patient==='No'?'selected':''}>No</option><option ${d.patient==='Yes'?'selected':''}>Yes</option><option ${d.patient==='Not yet established'?'selected':''}>Not yet established</option></select>`:''}<label for="immediate">What immediate action was taken?</label><textarea id="immediate" name="immediate" required maxlength="2500" placeholder="e.g. Pharmacist informed; issue corrected before supply.">${esc(d.immediate)}</textarea><label class="checkbox"><input type="checkbox" name="notified" required ${d.notified?'checked':''}>I have notified the pharmacist or responsible person for this demonstration scenario.</label><div class="dialog-actions">${btn('Back','report-back','ghost')}<button class="button" type="submit">Review report ${icon('arrow')}</button></div></form>`;}
 if(reportStep===3){body=track+`<div class="review-block"><span class="eyebrow muted">${esc(d.type)} · ${siteName(d.site)}</span><h3 style="margin-top:12px">${esc(d.title)}</h3><p>${esc(d.description)}</p></div><dl class="detail-grid"><div><dt>Category / stage</dt><dd>${esc(d.category)} · ${esc(d.stage)}</dd></div><div><dt>Reached the patient</dt><dd>${['Near miss','Medication error'].includes(d.type)?esc(d.patient):'Not applicable'}</dd></div></dl><h3>Immediate response</h3><p class="small muted" style="margin-top:10px;white-space:pre-wrap">${esc(d.immediate)}</p>${d.photo?`<img class="attachment" src="${d.photo}" alt="Demo evidence attachment">`:''}<div class="notice green section">Saving creates a local demo record awaiting review. No pharmacist is notified by this prototype.</div><div class="dialog-actions">${btn('Back','report-back','ghost')}${btn('Save report '+icon('tick'),'save-report','')}</div>`;}
 modal(['','Tell us what happened.','What happened next?','Ready to record.'][reportStep],body,esc(d.type));if(reportStep===1)$('#form-site').value=d.site;
}
function reportDetail(id){const r=state.reports.find(x=>x.id===id);if(!r)return;const linked=state.actions.filter(a=>a.source===id);modal(esc(r.title),`<div class="buttons">${badge(r.type,r.type==='Medication error'?'red':'gray')}${badge(r.status,r.status==='Closed'?'':'amber')}</div><dl class="detail-grid"><div><dt>Pharmacy</dt><dd>${siteName(r.site)}</dd></div><div><dt>Identified / recorded</dt><dd>${r.identified?esc(r.identified.replace('T',' ')):formatDate(r.date)} · ${r.id}</dd></div><div><dt>Category / stage</dt><dd>${esc(r.category)} · ${esc(r.stage)}</dd></div><div><dt>Reached the patient / impact</dt><dd>${esc(r.patient)} · ${esc(r.severity)}</dd></div></dl>${r.medicineIntended||r.medicineObserved?`<dl class="detail-grid"><div><dt>Intended medicine / strength</dt><dd>${esc(r.medicineIntended||'Not recorded')}</dd></div><div><dt>Selected / supplied</dt><dd>${esc(r.medicineObserved||'Not recorded')}</dd></div></dl>`:''}${r.factor?`<p class="small muted" style="margin-bottom:20px">Possible contributing factor: ${esc(r.factor)}</p>`:''}<h3>What happened</h3><p class="small muted" style="white-space:pre-wrap;margin-top:9px">${esc(r.description)}</p><h3 style="margin-top:22px">Immediate response</h3><p class="small muted" style="white-space:pre-wrap;margin-top:9px">${esc(r.immediate)}</p>${r.photo?`<img class="attachment" src="${r.photo}" alt="Demo evidence">`:''}<section class="section"><h3>Follow-up actions</h3>${linked.map(a=>row(esc(a.title),esc(a.owner)+' · '+esc(a.status),'action','action:'+a.id)).join('')||'<p class="muted small" style="margin-top:10px">No linked actions yet.</p>'}${reviewer()&&r.status!=='Closed'?btn('Add a preventive action','new-action:'+id,'ghost'):''}</section>${r.review?`<section class="section"><h3>Review outcome</h3><p class="muted small" style="white-space:pre-wrap;margin-top:10px">${esc(r.review)}</p></section>`:''}<section class="section"><h3>Record history</h3><div class="timeline">${r.timeline.map(t=>`<div class="timeline-item">${esc(t.text)}<p>${esc(t.time)}</p></div>`).join('')}</div></section>${reviewer()&&r.status!=='Closed'?`<form id="review-report" data-id="${id}"><label for="patient-impact">Patient impact · pharmacist assessment</label><select id="patient-impact" name="severity"><option ${r.severity==='Requires pharmacist assessment'?'selected':''}>Requires pharmacist assessment</option><option ${r.severity==='No harm identified'?'selected':''}>No harm identified</option><option ${r.severity==='Harm identified; restricted clinical record updated'?'selected':''}>Harm identified; restricted clinical record updated</option><option>Not applicable</option></select><label for="review-note">Pharmacist review / learning</label><textarea id="review-note" name="review" required placeholder="Record the review outcome and learning. Use fictional information." maxlength="2500"></textarea><div class="buttons section"><button class="button secondary" name="outcome" value="In review" type="submit">Save review</button><button class="button" name="outcome" value="Closed" type="submit" ${linked.some(a=>a.status!=='Closed')?'disabled':''}>Close report</button></div>${linked.some(a=>a.status!=='Closed')?'<p class="field-note">Close linked actions before closing this report.</p>':''}</form>`:!reviewer()?'<p class="notice section">Pharmacist review is available in the Pharmacist and Group admin demo views.</p>':''}`,r.id);}
function sopDetail(id){const s=visibleSops().find(x=>x.id===id);if(!s)return;const ack=state.acknowledgements.some(a=>a.sop===id&&a.version===s.version&&a.site===state.site&&a.role===state.role);modal(esc(s.title),`<div class="notice">Illustrative draft content for demonstration. “Demo current” means current within this prototype, not approved by Stacks. Follow the pharmacy’s actual approved SOPs in practice.</div><dl class="detail-grid"><div><dt>Version / status</dt><dd>v${esc(s.version)} · ${esc(s.status)}</dd></div><div><dt>Applicable to</dt><dd>${esc(s.scope)}</dd></div><div><dt>Document owner</dt><dd>${esc(s.owner)}</dd></div><div><dt>Demo effective / review dates</dt><dd>${formatDate(s.effective)} / ${formatDate(s.review)}</dd></div></dl><div class="sop-body"><h3>Purpose</h3><p>${esc(s.objective)}</p><h3>Responsibilities</h3><p>Colleagues follow the procedure relevant to their role. The supervising pharmacist oversees local implementation; the superintendent pharmacist approves the production SOP.</p><h3>Illustrative workflow</h3><ol>${s.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h3>Evidence and escalation</h3><p>Record the relevant check, report or action. Escalate any patient safety concern promptly to the pharmacist; the app does not make clinical decisions.</p><h3>Source context</h3><p><a href="${esc(s.source)}" target="_blank" rel="noopener">View the official guidance used to shape this example ${icon('arrow')}</a></p><p class="small muted">The sample is a product-design illustration, not a reproduction or complete implementation of the guidance.</p></div>${s.history.length?`<section class="section"><h3>Version history</h3>${s.history.map(h=>`<div class="row"><div class="row-content"><h3>v${esc(h.version)} · Previous demo version</h3><p>${esc(h.note)}</p></div></div>`).join('')}</section>`:''}<div class="dialog-actions"><div>${groupAdmin()?btn('Revise sample','revise-sop:'+id,'secondary'):btn('Print','print','secondary')}</div>${s.status==='Draft'?groupAdmin()?btn('Publish demo version','publish-sop:'+id,''):badge('Draft','amber'):ack?badge('Acknowledged'):state.site!=='all'?btn('I have read this sample','ack:'+id,''):badge('Choose a site to acknowledge','gray')}</div>`,s.id);}
function editSop(id=''){if(!groupAdmin())return;const s=state.sops.find(x=>x.id===id);modal(s?'Revise this sample.':'Add a sample procedure.',`<form id="edit-sop" data-id="${id}"><div class="notice">This edits demonstration content only. A production revision requires the client’s authorised approval workflow.</div><label for="sop-title">Title</label><input id="sop-title" name="title" value="${esc(s?.title||'')}" required maxlength="120"><label for="sop-purpose">Purpose</label><textarea id="sop-purpose" name="objective" required maxlength="1000">${esc(s?.objective||'')}</textarea><label for="sop-steps">Workflow steps · one per line</label><textarea id="sop-steps" name="steps" required maxlength="5000">${esc(s?.steps.join('\n')||'')}</textarea><label for="sop-note">Reason for change</label><input id="sop-note" name="note" required maxlength="250" placeholder="e.g. Learning from PT-1001">${formFooter(s?'Save draft revision':'Create draft')}</form>`,'Document control');}
function checkDialog(id){if(state.site==='all'){toast('Choose a pharmacy first.');return;}const t=CHECK_TEMPLATES.find(t=>t.id===id);if(!t)return;const existing=state.checks.find(c=>c.site===state.site&&c.template===id&&c.date===DEMO_DATE);if(existing){checkRecord(existing.id);return;}modal(t.title,`<form id="record-check" data-template="${id}"><p class="muted small">${siteName(state.site)} · Demo day 5 October · ${t.time}</p>${t.type==='list'?t.items.map((x,i)=>`<label class="checkbox"><input type="checkbox" name="item${i}" required>${x}</label>`).join(''):`<div class="grid three">${[['current','Current'],['min','Minimum'],['max','Maximum']].map(([n,l])=>`<div><label for="${n}">${l} °C</label><input id="${n}" name="${n}" type="number" step="0.1" min="-50" max="80" required placeholder="${n==='current'?'4.2':n==='min'?'3.8':'5.1'}"></div>`).join('')}</div><div class="notice section">Enter all three readings, including excursions. An out-of-range reading creates a pharmacist review action in this demo.</div>`}<label for="check-note">Note · optional</label><textarea id="check-note" name="note" maxlength="1000" placeholder="Any relevant observation"></textarea>${btn('Read sample procedure','sop:'+t.sop,'ghost')}<p id="check-error" class="form-error" role="alert"></p>${formFooter('Save check')}</form>`,'Daily check');}
function checkRecord(id){const c=state.checks.find(x=>x.id===id);if(!c)return;const t=CHECK_TEMPLATES.find(t=>t.id===c.template);modal(t.title,`${badge(c.result,c.result==='Needs review'?'amber':'')}<dl class="detail-grid"><div><dt>Pharmacy / date</dt><dd>${siteName(c.site)} · ${formatDate(c.date)}</dd></div><div><dt>Recorded by</dt><dd>${esc(c.by)}</dd></div>${c.current!==undefined?`<div><dt>Current</dt><dd>${c.current}°C</dd></div><div><dt>Minimum / maximum</dt><dd>${c.min}°C / ${c.max}°C</dd></div>`:''}</dl>${c.note?`<p class="small muted">${esc(c.note)}</p>`:''}<p class="notice green">This record remains in the demo history. Correcting records in production requires a traceable amendment, rather than overwriting evidence.</p><div class="buttons section">${btn('View sample procedure','sop:'+t.sop,'secondary')}${c.result==='Needs review'?btn('View actions','close-nav:actions',''):''}</div>`,c.id);}
function maintenanceForm(){modal('What needs attention?',`<form id="new-maintenance">${siteField()}<label for="fault-title">Title</label><input id="fault-title" name="title" required maxlength="120" placeholder="e.g. Fridge alarm sounding"><label for="asset">Equipment or area</label><input id="asset" name="asset" required maxlength="120" placeholder="e.g. Pharmaceutical fridge FR-01"><label for="fault-details">Describe the issue</label><textarea id="fault-details" name="description" required maxlength="2000"></textarea><label for="priority">Priority</label><select id="priority" name="priority"><option>Normal</option><option>Urgent</option></select><div class="notice section">If medicines or people may be at risk, notify the pharmacist or responsible person immediately. This demo does not send notifications.</div><label for="fault-photo">Optional evidence image</label><input id="fault-photo" type="file" accept="image/*" capture="environment"><p class="field-note">No patient information · maximum 500 KB.</p>${formFooter('Save fault')}</form>`,'Maintenance');}
function maintenanceDetail(id){const m=state.maintenance.find(x=>x.id===id);if(!m)return;modal(esc(m.title),`${badge(m.status,m.status==='Completed'?'':'amber')}<dl class="detail-grid"><div><dt>Asset</dt><dd>${esc(m.asset)}</dd></div><div><dt>Pharmacy</dt><dd>${siteName(m.site)}</dd></div><div><dt>Priority</dt><dd>${esc(m.priority)}</dd></div><div><dt>Owner</dt><dd>${esc(m.owner)}</dd></div></dl><p class="small muted">${esc(m.description)}</p>${m.photo?`<img class="attachment" src="${m.photo}" alt="Fault evidence">`:''}${m.evidence?`<section class="section"><h3>Completion evidence</h3><p class="small muted" style="margin-top:10px">${esc(m.evidence)}</p></section>`:''}${m.status!=='Completed'&&reviewer()?`<form id="complete-maintenance" data-id="${id}"><label for="maintenance-evidence">Service or repair evidence</label><textarea id="maintenance-evidence" name="evidence" required maxlength="2000" placeholder="What was done, by whom, and what return-to-service checks were completed?"></textarea><label class="checkbox"><input type="checkbox" required>I have checked the equipment’s return-to-service evidence in this demo.</label>${formFooter('Record completion')}</form>`:''}<div class="buttons section">${btn('Related procedure','sop:SOP-009','secondary')}</div>`,m.id);}
function actionForm(source=''){if(!reviewer())return;const r=state.reports.find(x=>x.id===source);modal('Give the next step an owner.',`<form id="new-action" data-source="${source}">${siteField()}<label for="action-title">Action</label><input id="action-title" name="title" required maxlength="160" placeholder="e.g. Review shelf separation"><label for="action-owner">Owner</label><select name="owner" id="action-owner"><option>Supervising pharmacist</option><option>Pharmacy manager</option><option>Group governance team</option><option>Demo colleague</option></select><label for="action-due">Due date</label><input type="date" id="action-due" name="due" required value="2026-10-06"><label for="action-source">Source</label><input name="source" id="action-source" value="${esc(source||'Operational review')}" required maxlength="120">${formFooter('Create action')}</form>`,'Corrective & preventive action');if(r)$('#form-site').value=r.site;}
function actionDetail(id){const a=state.actions.find(a=>a.id===id);if(!a)return;const related=state.reports.find(r=>r.id===a.source)||state.maintenance.find(m=>m.id===a.source);modal(esc(a.title),`${badge(a.status,a.status==='Closed'?'':'amber')}<dl class="detail-grid"><div><dt>Owner</dt><dd>${esc(a.owner)}</dd></div><div><dt>Pharmacy</dt><dd>${siteName(a.site)}</dd></div><div><dt>Due</dt><dd>${formatDate(a.due)}</dd></div><div><dt>Linked record</dt><dd>${related?btn(esc(a.source),a.source.startsWith('PT')?'report:'+a.source:'maintenance:'+a.source,'ghost'):esc(a.source)}</dd></div></dl>${a.evidence?`<h3>Completion evidence</h3><p class="small muted" style="margin-top:10px;white-space:pre-wrap">${esc(a.evidence)}</p>`:''}${a.review?`<h3 style="margin-top:22px">Effectiveness review</h3><p class="small muted" style="margin-top:10px;white-space:pre-wrap">${esc(a.review)}</p>`:''}${a.status==='Open'?`<form id="submit-action" data-id="${id}"><label for="action-evidence">What was completed?</label><textarea id="action-evidence" name="evidence" required maxlength="2000" placeholder="Record the outcome and supporting evidence."></textarea>${formFooter('Submit for review')}</form>`:a.status==='Awaiting review'&&reviewer()?`<form id="review-action" data-id="${id}"><label for="action-review">Was the action effective?</label><textarea id="action-review" name="review" required maxlength="2000" placeholder="Explain how you checked the outcome and whether further work is needed."></textarea><div class="dialog-actions">${btn('Return for more work','reopen-action:'+id,'secondary')}<button class="button" type="submit">Confirm and close ${icon('tick')}</button></div></form>`:a.status==='Awaiting review'?'<p class="notice section">Awaiting an authorised reviewer. Switch to the Pharmacist demo view to see the review stage.</p>':''}`,a.id);}
function lessonDialog(id){if(state.site==='all'){toast('Choose a pharmacy to complete learning.');return;}const l=LESSONS.find(l=>l.id===id),s=knowledgeSop(l.sop);modal(l.title,`<p class="muted small">${l.minutes} minute sample refresher · ${l.sop}</p><div class="sop-body"><h3>The essentials</h3><ol>${s.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div><form id="lesson" data-id="${id}"><label>${l.question}</label>${l.answers.map((a,i)=>`<label class="checkbox"><input type="radio" name="answer" value="${i}" required>${a}</label>`).join('')}<p id="lesson-error" class="form-error" role="alert"></p>${formFooter('Check and complete')}</form>`,'Learning');}
function recallResponse(){if(state.site==='all')return;modal('Record site response',`<form id="recall-response"><p class="notice">Fictional recall exercise · ${siteName(state.site)} · batch DEMO-001</p><label for="quantity">Packs found</label><input type="number" id="quantity" name="quantity" min="0" max="10000" step="1" required value="0"><label for="recall-note">Response / evidence</label><textarea id="recall-note" name="note" required maxlength="2000" placeholder="Record the stock check, segregation if relevant and next steps."></textarea><label class="checkbox"><input type="checkbox" required>I have followed the sample exercise instructions.</label>${!reviewer()?'<p class="field-note">Staff responses are saved pending pharmacist confirmation.</p>':''}${formFooter(reviewer()?'Confirm site response':'Submit site response')}</form>`,'Recall response');}
const AUDIT_AREAS=['Current applicable SOPs accessible','Incident and near-miss records reviewed','Storage monitoring and exceptions reviewed','Equipment maintenance evidence available','Staff training and acknowledgements reviewed'];
function auditForm(){if(state.site==='all'){toast('Choose a pharmacy first.');return;}if(!reviewer()){toast('Use the Pharmacist view to record an internal review.');return;}modal('Internal review',`<form id="new-audit"><p class="muted small">${siteName(state.site)} · illustrative review, not a complete PSI assessment.</p>${AUDIT_AREAS.map((a,i)=>`<label for="audit-${i}">${a}</label><select id="audit-${i}" name="area${i}" required><option value="">Choose an outcome</option><option>Meets sample criteria</option><option>Needs improvement</option><option>Not applicable</option></select>`).join('')}<label for="audit-note">Review notes</label><textarea id="audit-note" name="note" required maxlength="2500" placeholder="Describe evidence checked and any findings."></textarea><div class="notice section">Each “Needs improvement” finding creates an assigned action due in seven days.</div>${formFooter('Save review and actions')}</form>`,'Internal review');}
function auditDetail(id){const a=state.audits.find(x=>x.id===id);modal(esc(a.title),`<p class="muted small">${siteName(a.site)} · ${formatDate(a.date)}</p><dl>${a.areas.map((outcome,i)=>`<div class="row"><div class="row-content"><h3>${AUDIT_AREAS[i]}</h3><p>${esc(outcome)}</p></div></div>`).join('')}</dl><p class="small muted" style="white-space:pre-wrap">${esc(a.note)}</p>${a.findings.length?btn('View follow-up actions','close-nav:actions','') : badge('No improvement findings')}`,'Internal review');}
function evidencePack(){const reports=scoped(state.reports),actions=scoped(state.actions),checks=scoped(state.checks),maintenance=scoped(state.maintenance);modal('Pharmacy evidence pack',`<p class="muted small">${siteLabel()} · Generated ${new Date().toLocaleDateString('en-IE')} · Demo operating day ${formatDate(DEMO_DATE)}</p><div class="notice section">Demonstration records and sample procedures only. This pack does not certify compliance.</div><section class="section"><h3>SOP register</h3><table><thead><tr><th>Procedure</th><th>Version</th><th>Status</th></tr></thead><tbody>${state.sops.map(s=>`<tr><td>${s.id} · ${esc(s.title)}</td><td>${esc(s.version)}</td><td>${esc(s.status)}</td></tr>`).join('')}</tbody></table></section><section class="section"><h3>Recorded checks</h3>${checks.map(c=>`<div class="row"><div class="row-content"><h3>${siteName(c.site)} · ${CHECK_TEMPLATES.find(t=>t.id===c.template)?.title}</h3><p>${formatDate(c.date)} · ${esc(c.result)}${c.current!==undefined?' · '+c.current+'°C / min '+c.min+'°C / max '+c.max+'°C':''}</p></div></div>`).join('')||'<p class="small muted">No check records in this scope.</p>'}</section><section class="section"><h3>Incident summaries</h3>${reports.map(r=>`<div class="row"><div class="row-content"><h3>${r.id} · ${esc(r.type)}</h3><p>${siteName(r.site)} · ${formatDate(r.date)} · ${esc(r.status)} · ${esc(r.category)}</p></div></div>`).join('')||'<p class="small muted">No incidents in this scope.</p>'}</section><section class="section"><h3>Maintenance</h3>${maintenance.map(m=>`<div class="row"><div class="row-content"><h3>${esc(m.title)}</h3><p>${siteName(m.site)} · ${esc(m.status)}</p></div></div>`).join('')||'<p class="small muted">No maintenance records in this scope.</p>'}</section><section class="section"><h3>Improvement actions</h3>${actions.map(a=>`<div class="row"><div class="row-content"><h3>${a.id} · ${esc(a.title)}</h3><p>${siteName(a.site)} · ${esc(a.owner)} · due ${formatDate(a.due)} · ${esc(a.status)}</p></div></div>`).join('')||'<p class="small muted">No actions in this scope.</p>'}</section><section class="section"><h3>Internal reviews</h3><p class="small muted">${scoped(state.audits).length} reviews recorded in this scope.</p></section><section class="section"><h3>Sample recall response</h3><p class="small muted">${state.recall.responses.filter(r=>state.site==='all'||r.site===state.site).length} site responses recorded for RC-DEMO-01.</p></section><div class="dialog-actions">${btn('Close','close','ghost')}${btn('Print / save as PDF','print','')}</div>`,'Inspection evidence');}
let askMessages=[];
function renderAsk(){if(!$('#ask-root'))return;$('#ask-root').innerHTML=`<section class="ask-panel" aria-label="Ask PharmaTap"><div class="ask-header"><img src="assets/mark.svg" alt=""><div><h3>Ask PharmaTap</h3></div><button class="close" data-action="ask-close" aria-label="Close assistant">${icon('close')}</button></div><div class="ask-feed" aria-live="polite"><div class="bubble">Find a sample procedure, start a report or see what needs attention at ${esc(siteLabel())}.<br><small class="muted">Demo responses · no live AI.</small></div>${askMessages.length?askMessages.map(m=>`<div class="bubble ${m.user?'user':''}">${m.user?esc(m.text):m.text}</div>`).join(''):`<button class="suggestion" data-prompt="How do I report a near miss?">How do I report a near miss?</button><button class="suggestion" data-prompt="Record a fridge check">Record a fridge check</button><button class="suggestion" data-prompt="What needs attention?">What needs attention?</button><button class="suggestion" data-prompt="Find the recall procedure">Find the recall procedure</button>`}</div><form class="ask-form" id="ask-form"><input id="ask-input" name="prompt" aria-label="Ask PharmaTap" placeholder="Ask, or tell me what happened…" autocomplete="off" maxlength="2000" required><button type="button" class="button secondary" data-action="dictate:ask-input" aria-label="Dictate a question">${icon('mic')}</button><button class="button" type="submit" aria-label="Send">${icon('arrow')}</button></form><p class="ask-disclaimer">Sample guidance only. Clinical questions belong with the pharmacist.</p></section>`;const feed=$('.ask-feed');feed.scrollTop=feed.scrollHeight;}
function askAnswer(prompt){const q=prompt.toLowerCase();let answer;
 if(/dose|dosage|interaction|can i take|side effect|pregnan|diagnos|treat|prescrib/.test(q)&&!/error|procedure|report|near miss/.test(q)){answer='A pharmacist needs to assess this clinical question using the appropriate clinical references. This demo cannot advise on medicine suitability, dosing or treatment.';}
 else if(/attention|overdue|outstanding|open action/.test(q)){const list=activeActions();answer=`There ${list.length===1?'is':'are'} <strong>${list.length} open ${list.length===1?'action':'actions'}</strong> in your selected scope.${list.length?'<ul>'+list.slice(0,4).map(a=>`<li>${esc(a.title)} · ${esc(dueLabel(a))}</li>`).join('')+'</ul>':' No outstanding actions are recorded.'}${btn('View actions','ask-nav:actions','secondary')}`;}
 else if(/fridge|temperature|cold chain/.test(q)){const s=knowledgeSop('SOP-003');answer=`The sample fridge workflow records <strong>current, minimum and maximum</strong> readings. Any excursion should be escalated to the pharmacist using the actual approved procedure.<br><small class="muted">Sample source: ${s.id} · v${esc(s.version)} · illustrative workflow steps 1–3</small><div class="buttons">${btn('Open sample SOP','sop:SOP-003','secondary')}${btn('Record a check','ask-check:fridge','')}</div>`;}
 else if(/near miss|error|report|wrong strength|wrong medicine/.test(q)){const near=/near miss|caught|intercept/.test(q),s=knowledgeSop(near?'SOP-002':'SOP-001');answer=`${near?'Record what was intercepted, the stage and contributing factors; notify the pharmacist.':'Notify the pharmacist promptly. Patient care takes priority over completing the report.'} I can open a structured report for you to review before saving.<br><small class="muted">Sample source: ${s.id} · v${esc(s.version)} · illustrative workflow</small><div class="buttons">${btn('Open sample SOP','sop:'+s.id,'secondary')}${btn('Start report','ask-report:'+(near?'Near miss':'Medication error'),'')}</div>`;}
 else if(/recall|quarantine/.test(q)){answer=`Follow the <strong>actual recall notice</strong> for the product and batch involved. The sample workflow demonstrates identification, segregation, return evidence and pharmacist confirmation.<br><small class="muted">Sample source: SOP-006 · v${esc(knowledgeSop('SOP-006').version)} · illustrative workflow</small><div class="buttons">${btn('Open sample SOP','sop:SOP-006','secondary')}${btn('View recall exercise','ask-nav:recalls','')}</div>`;}
 else if(/maintenance|fault|broken|repair|alarm/.test(q)){answer=`Record the equipment, issue and operational impact. If people or medicines may be at risk, notify the pharmacist or responsible person immediately.<br><small class="muted">Sample source: SOP-009 · illustrative workflow</small>${btn('Report a fault','new-maintenance','')}`;}
 else if(/check|today/.test(q)){answer=`Your sample daily schedule covers fridge and room readings, opening checks, cleaning and closing.${btn('Open today’s checks','ask-nav:checks','')}`;}
 else {const words=q.split(/\s+/).filter(w=>w.length>3),matches=state.sops.map(publishedSop).filter(Boolean).map(s=>({s,n:words.filter(w=>(s.title+' '+s.objective).toLowerCase().includes(w)).length})).filter(x=>x.n).sort((a,b)=>b.n-a.n).slice(0,3);answer=matches.length?`These sample procedures may help:<div>${matches.map(({s})=>btn(esc(s.title),'sop:'+s.id,'secondary')).join(' ')}</div>`:`I don’t have an applicable answer in this demo. Try a procedure topic, “record a near miss” or “what needs attention?”. The production assistant would search only the current approved SOPs available to your role and site.${btn('Browse sample procedures','ask-nav:sops','secondary')}`;}
 askMessages.push({user:true,text:prompt},{text:answer});renderAsk();
}
let recognition;
function dictate(target){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('Voice dictation is unavailable in this browser. You can type instead.');return;}if(recognition){recognition.stop();return;}const input=$('#'+target);if(!input)return;recognition=new Speech();recognition.lang='en-IE';recognition.interimResults=false;recognition.continuous=false;recognition.onresult=e=>{input.value=(input.value?input.value+' ':'')+e.results[0][0].transcript;input.focus();toast('Dictation added. Review and edit before sending.');};recognition.onerror=()=>toast('Voice could not start. Please type your account.');recognition.onend=()=>{recognition=null;};try{recognition.start();toast('Listening… speak, then pause.');}catch{recognition=null;toast('Voice is unavailable. Please type instead.');}}
function exportData(){const blob=new Blob([JSON.stringify({product:'PharmaTap Stacks demo',exported:new Date().toISOString(),demoDate:DEMO_DATE,data:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='PharmaTap-Demo-Records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo records exported.');}
function act(action){const [name,...rest]=action.split(':'),id=rest.join(':');switch(name){
 case 'back':goBack();break;case 'nav':navigate(id);break;case 'menu':askOpen=false;navChoice='menu';mobileOpen=!mobileOpen;render();break;case 'close':closeModal();break;case 'close-nav':closeModal();navigate(id);break;
 case 'ask':navChoice='ask';mobileOpen=false;askOpen=true;render();$('#ask-input').focus();break;case 'ask-close':if(recognition)recognition.stop();askOpen=false;navChoice=page==='today'?'home':'menu';render();break;case 'ask-nav':askOpen=false;navigate(id);break;case 'ask-check':askOpen=false;render();checkDialog(id);break;case 'ask-report':askOpen=false;render();newReport(id);break;case 'dictate':dictate(id);break;
 case 'new-report':newReport();break;case 'report-type':reportDraft.type=id;reportDraft.patient=id==='Near miss'?'No':'Yes';reportStep=1;reportWizard();break;
 case 'report-back':if(reportStep===1){const f=$('#report-facts');Object.assign(reportDraft,Object.fromEntries(new FormData(f)));}else if(reportStep===2){const f=$('#report-response');Object.assign(reportDraft,Object.fromEntries(new FormData(f)));}reportStep=Math.max(0,reportStep-1);reportWizard();break;
 case 'save-report':{if(!reportDraft)return;const r={...reportDraft,id:'PT-'+(1001+state.reports.length),status:'Awaiting review',date:DEMO_DATE,owner:'Demo pharmacist',actions:[],timeline:[{text:'Report submitted by '+state.role+' demo user',time:new Date().toLocaleString('en-IE')}]};state.reports.push(r);save('Report '+r.id+' submitted for review',r.site);closeModal();navigate('reports');toast('Report saved. Awaiting demo pharmacist review.');reportDetail(r.id);break;}
 case 'report':reportDetail(id);break;case 'sop':sopDetail(id);break;case 'revise-sop':editSop(id);break;case 'new-sop':editSop();break;
 case 'publish-sop':{if(!groupAdmin())return;const s=state.sops.find(s=>s.id===id);s.status='Demo current';s.effective=DEMO_DATE;save('Published sample '+id+' v'+s.version+' in demo','group');render();sopDetail(id);toast('Demo version published. Earlier acknowledgements remain in history.');break;}
 case 'ack':{const s=knowledgeSop(id);if(!s)return;if(state.site==='all'||s.status==='Draft')return;state.acknowledgements.push({sop:id,version:s.version,site:state.site,role:state.role,time:new Date().toISOString()});save('Acknowledged sample '+id+' v'+s.version);render();sopDetail(id);toast('Sample procedure acknowledged.');break;}
 case 'check':checkDialog(id);break;case 'check-record':checkRecord(id);break;case 'new-maintenance':maintenanceForm();break;case 'maintenance':maintenanceDetail(id);break;case 'new-action':actionForm(id);break;case 'action':actionDetail(id);break;
 case 'reopen-action':{if(!reviewer())return;const a=state.actions.find(a=>a.id===id),note=$('#action-review')?.value.trim();if(!note){toast('Add a review note explaining what further work is needed.');return;}a.review=note;a.status='Open';save('Action '+id+' returned for further work',a.site);render();actionDetail(id);break;}
 case 'lesson':lessonDialog(id);break;case 'recall-response':recallResponse();break;case 'recall-confirm':{if(!reviewer())return;const r=state.recall.responses.find(r=>r.site===id);r.status='Confirmed';r.by='Demo '+state.role;save('Recall response confirmed for '+siteName(id),id);render();toast('Demo response confirmed.');break;}
 case 'new-audit':auditForm();break;case 'audit':auditDetail(id);break;case 'print-pack':evidencePack();break;case 'print':window.print();break;case 'site':state.site=id;save();navigate('today');break;
 case 'export':exportData();break;case 'reset':modal('Start fresh?',`<p class="muted">This removes the changes made in this browser and restores the fictional demonstration records. Export anything you want to keep first.</p><div class="dialog-actions">${btn('Keep changes','close','secondary')}${btn('Reset demo','confirm-reset','danger')}</div>`,'Demo workspace');break;
 case 'confirm-reset':state=seedState();askMessages=[];save();closeModal();navigate('today');toast('Demo restored.');break;
 }}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}const action=e.target.closest('[data-action]');if(action){act(action.dataset.action);return;}const tr=e.target.closest('[data-id]');if(tr&&tr.tagName==='TR'){act(tr.dataset.id);return;}const prompt=e.target.closest('[data-prompt]');if(prompt)askAnswer(prompt.dataset.prompt);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&mobileOpen){mobileOpen=false;render();$('.mobile-navigation [data-action=menu]')?.focus();return;}if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-id]')){e.preventDefault();act(e.target.dataset.id);}});
document.addEventListener('change',e=>{if(e.target.id==='site-select'){state.site=e.target.value;askMessages=[];save();render();}if(e.target.id==='role-select'){state.role=e.target.value;if(!groupAdmin()&&state.site==='all')state.site='skerries';askMessages=[];save();render();}if(e.target.id==='filter'){filter=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const start=e.target.selectionStart;search=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(start,start);}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'today';if(next!==page){pageHistory.push({page,filter,search,scroll:window.scrollY});page=next;filter='';search='';mobileOpen=false;render();}});
$('#dialog').addEventListener('click',e=>{if(e.target.id==='dialog'){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
async function photoData(input){const f=input?.files?.[0];if(!f)return '';if(f.size>500000)throw new Error('Choose an evidence image smaller than 500 KB.');if(!['image/jpeg','image/png','image/webp','image/gif'].includes(f.type))throw new Error('Choose a JPEG, PNG, WebP or GIF image.');return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('Could not read the image.'));r.readAsDataURL(f);});}
function addAction(a){const x={id:'A-'+(1001+state.actions.length),status:'Open',evidence:'',review:'',...a};state.actions.push(x);return x;}
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id)return;e.preventDefault();if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));try{switch(f.id){
 case 'ask-form':askAnswer(v.prompt.trim());break;
 case 'report-facts':{const photo=await photoData($('#photo'));Object.assign(reportDraft,v);if(photo)reportDraft.photo=photo;reportStep=2;reportWizard();break;}
 case 'report-response':Object.assign(reportDraft,v);if(reportDraft.type==='Near miss')reportDraft.patient='No';if(!['Near miss','Medication error'].includes(reportDraft.type))reportDraft.patient='Not applicable';reportStep=3;reportWizard();break;
 case 'review-report':{if(!reviewer())return;const r=state.reports.find(r=>r.id===f.dataset.id),outcome=e.submitter?.value||'In review';if(outcome==='Closed'&&state.actions.some(a=>a.source===r.id&&a.status!=='Closed')){toast('Linked actions still need review.');return;}r.review=v.review;r.severity=v.severity;r.status=outcome;r.timeline.push({text:'Demo pharmacist review saved · '+outcome,time:new Date().toLocaleString('en-IE')});save('Report '+r.id+' reviewed: '+outcome,r.site);render();reportDetail(r.id);toast('Review saved.');break;}
 case 'edit-sop':{if(!groupAdmin())return;const steps=v.steps.split('\n').map(s=>s.trim()).filter(Boolean);if(!steps.length){toast('Add at least one workflow step.');return;}let s=state.sops.find(s=>s.id===f.dataset.id);if(s){if(s.status!=='Draft'){s.history.unshift({version:s.version,status:s.status,effective:s.effective,review:s.review,title:s.title,objective:s.objective,steps:[...s.steps],note:v.note,time:new Date().toISOString()});const n=Number(s.version)+.1;s.version=n.toFixed(1);}s.title=v.title;s.objective=v.objective;s.steps=steps;s.status='Draft';}else{s={...structuredClone(SOP_LIBRARY[14]),id:'SOP-'+String(state.sops.length+1).padStart(3,'0'),title:v.title,objective:v.objective,steps,history:[],status:'Draft'};state.sops.push(s);}save('Draft sample '+s.id+' v'+s.version+' saved: '+v.note,'group');render();sopDetail(s.id);toast('Draft saved. Review it before publishing the demo version.');break;}
 case 'record-check':{const t=CHECK_TEMPLATES.find(t=>t.id===f.dataset.template);if(state.checks.some(c=>c.site===state.site&&c.template===t.id&&c.date===DEMO_DATE)){toast('This check has already been recorded.');return;}const c={id:'CK-'+crypto.randomUUID().slice(0,8),site:state.site,template:t.id,date:DEMO_DATE,note:v.note,by:'Demo '+state.role,result:'Completed'};if(t.type!=='list'){c.current=Number(v.current);c.min=Number(v.min);c.max=Number(v.max);if(c.min>c.current||c.current>c.max){$('#check-error').textContent='Minimum must be at or below current; maximum must be at or above current. Keep true excursion readings.';return;}const fail=t.type==='temperature'?[c.current,c.min,c.max].some(n=>n<2||n>8):[c.current,c.min,c.max].some(n=>n>=25);c.result=fail?'Needs review':'Within demo limits';if(fail)addAction({site:state.site,title:'Review '+t.title.toLowerCase()+' temperature excursion',owner:'Supervising pharmacist',due:DEMO_DATE,source:c.id});}state.checks.push(c);save('Check '+t.title+' recorded: '+c.result);closeModal();render();toast(c.result==='Needs review'?'Check recorded. A demo pharmacist review action was created.':'Check recorded.');break;}
 case 'new-maintenance':{const photo=await photoData($('#fault-photo'));const m={...v,id:'M-'+(1001+state.maintenance.length),status:'Open',owner:'Pharmacy manager',date:DEMO_DATE,evidence:'',photo};state.maintenance.push(m);addAction({site:m.site,title:'Arrange review: '+m.title,owner:'Pharmacy manager',due:m.priority==='Urgent'?DEMO_DATE:'2026-10-07',source:m.id});save('Fault '+m.id+' reported with a linked action',m.site);closeModal();navigate('maintenance');toast('Fault saved and a follow-up action created.');break;}
 case 'complete-maintenance':{if(!reviewer())return;const m=state.maintenance.find(m=>m.id===f.dataset.id);m.evidence=v.evidence;m.status='Completed';state.actions.filter(a=>a.source===m.id&&a.status==='Open').forEach(a=>{a.evidence=v.evidence;a.status='Awaiting review';});save('Maintenance '+m.id+' completed; linked actions await review',m.site);render();maintenanceDetail(m.id);toast('Completion saved. Review the linked action to close it.');break;}
 case 'new-action':{if(!reviewer())return;const a=addAction(v),r=state.reports.find(r=>r.id===a.source);if(r){r.actions.push(a.id);r.timeline.push({text:'Preventive action '+a.id+' assigned',time:new Date().toLocaleString('en-IE')});}save('Action '+a.id+' assigned to '+a.owner,a.site);closeModal();navigate('actions');toast('Action created.');break;}
 case 'submit-action':{const a=state.actions.find(a=>a.id===f.dataset.id);a.evidence=v.evidence;a.status='Awaiting review';save('Completion evidence submitted for '+a.id,a.site);render();actionDetail(a.id);toast('Evidence saved for review.');break;}
 case 'review-action':{if(!reviewer())return;const a=state.actions.find(a=>a.id===f.dataset.id);a.review=v.review;a.status='Closed';save('Effectiveness reviewed and action '+a.id+' closed',a.site);render();actionDetail(a.id);toast('Action reviewed and closed.');break;}
 case 'lesson':{const l=LESSONS.find(l=>l.id===f.dataset.id);if(Number(v.answer)!==l.correct){$('#lesson-error').textContent='Take another look at the essentials above and try again.';return;}if(!state.learning.some(x=>x.id===l.id&&x.site===state.site&&x.role===state.role))state.learning.push({id:l.id,site:state.site,role:state.role,time:new Date().toISOString()});save('Sample refresher completed: '+l.title);closeModal();render();toast('Refresher completed.');break;}
 case 'recall-response':{if(state.recall.responses.some(r=>r.site===state.site)){toast('A response is already recorded for this site.');return;}state.recall.responses.push({site:state.site,quantity:Number(v.quantity),note:v.note,status:reviewer()?'Confirmed':'Awaiting review',by:'Demo '+state.role});save('Recall exercise response recorded');closeModal();render();toast(reviewer()?'Demo recall response confirmed.':'Response saved, awaiting demo pharmacist confirmation.');break;}
 case 'new-audit':{if(!reviewer())return;const areas=AUDIT_AREAS.map((_,i)=>v['area'+i]),findings=AUDIT_AREAS.filter((_,i)=>areas[i]==='Needs improvement'),a={id:'AU-'+(1001+state.audits.length),title:'Internal pharmacy review',site:state.site,date:DEMO_DATE,areas,findings,note:v.note};state.audits.push(a);findings.forEach(title=>addAction({site:state.site,title:'Internal review: '+title,owner:'Supervising pharmacist',due:'2026-10-12',source:a.id}));save('Internal review '+a.id+' saved with '+findings.length+' findings');closeModal();render();toast('Review saved. '+findings.length+' follow-up actions created.');break;}
 }}catch(err){toast(err.message||'Could not save. Please try again.');}});
render();
